export type BrandIcon = { viewBox: string; body: string };

export function brandIcon(name: string): BrandIcon | undefined {
  if (custom[name]) return custom[name];
  const path = paths[name];
  return path
    ? { viewBox: '0 0 24 24', body: `<path d="${path}"/>` }
    : undefined;
}
